import codecs,sys,unicodedata,hashlib,json,itertools,platform
assert sys.version_info[:3] == (3,14,7)
assert unicodedata.unidata_version == '16.0.0'
def attempt(f):
 try:
  result=f()
  return ['ok', list(result) if isinstance(result,bytes) else list(map(ord,result))]
 except (UnicodeEncodeError,UnicodeDecodeError) as e:
  return ['error', list(e.object) if isinstance(e.object,bytes) else list(map(ord,e.object)),e.start,e.end,e.reason]
def add(h,row): h.update((json.dumps(row,separators=(',',':'),ensure_ascii=True)+'\n').encode('ascii'))
results=[]
for policy in ('strict','ignore','replace'):
 for mode in (0,1,2):
  h=hashlib.sha256();count=0
  for a in range(256):
   for b in range(256):
    d=codecs.getincrementaldecoder('hz')(policy);d.setstate((b'',0x123400+mode))
    row=[]
    for chunk,final in [(bytes([a]),False),(bytes([b]),False),(b'',True),(b'~}A',True)]:
     row.append(attempt(lambda:d.decode(chunk,final)))
     pending,state=d.getstate();row.append([list(pending),str(state)])
    add(h,row);count+=1
  results.append(dict(kind='decode',policy=policy,mode=mode,count=count,digest=h.hexdigest()))
 alphabet=[65,126,10,0x4e2d,0x6587,0x30fb,0x2015,0xd800,0x1f600]
 h=hashlib.sha256();count=0
 for points in itertools.product(alphabet,repeat=3):
  s=''.join(map(chr,points))
  for split in range(4):
   e=codecs.getincrementalencoder('hz')(policy)
   row=[attempt(lambda:s.encode('hz',policy))]
   for chunk,final in [(s[:split],False),(s[split:],False),('',True),('A',True)]:
    row.extend([attempt(lambda:e.encode(chunk,final)),str(e.getstate())])
   add(h,row);count+=1
 results.append(dict(kind='encode',policy=policy,count=count,digest=h.hexdigest()))
 if policy!='strict':
  out=''.join(map(chr,range(0x110000))).encode('hz',policy)
  results.append(dict(kind='all-points',policy=policy,length=len(out),digest=hashlib.sha256(out).hexdigest()))
print(json.dumps(dict(reference=dict(version=sys.version,unicode=unicodedata.unidata_version,platform=platform.platform(),machine=platform.machine(),byteorder=sys.byteorder),results=results),indent=2))

